@Override
public boolean equals(Object o) {
    if (this == o) {
        return true;
    }
    if (o == null || getClass() != o.getClass()) {
        return false;
    }
    Step step = (Step) o;
    return keyIndex == step.keyIndex && Objects.equals(nameState, step.nameState) && Objects.equals(candidateSubRuleIds, step.candidateSubRuleIds);
}
